-- AscEmu Forever: complete Classic teleport AreaTrigger source volumes missing from Forever AreaTrigger.db2.
-- Source geometry: AzerothCore classic areatrigger data. Only IDs absent from the supplied Forever 1.60.1 AreaTrigger.db2 are inserted.
-- 2527/2532 are intentionally omitted: target teleports exist in old DBs, but no reliable source geometry is present in the reference AreaTrigger table.

CREATE TABLE IF NOT EXISTS `areatrigger_spawns` (
  `entry` INT UNSIGNED NOT NULL,
  `map` INT UNSIGNED NOT NULL DEFAULT 0,
  `position_x` FLOAT NOT NULL DEFAULT 0,
  `position_y` FLOAT NOT NULL DEFAULT 0,
  `position_z` FLOAT NOT NULL DEFAULT 0,
  `radius` FLOAT NOT NULL DEFAULT 0,
  `box_x` FLOAT NOT NULL DEFAULT 0,
  `box_y` FLOAT NOT NULL DEFAULT 0,
  `box_z` FLOAT NOT NULL DEFAULT 0,
  `orientation` FLOAT NOT NULL DEFAULT 0,
  `min_build` INT UNSIGNED NOT NULL DEFAULT 0,
  `max_build` INT UNSIGNED NOT NULL DEFAULT 2147483647,
  PRIMARY KEY (`entry`, `min_build`, `max_build`),
  KEY `idx_areatrigger_spawns_map_build` (`map`, `min_build`, `max_build`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE
  `map`=VALUES(`map`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`),
  `radius`=VALUES(`radius`), `box_x`=VALUES(`box_x`), `box_y`=VALUES(`box_y`), `box_z`=VALUES(`box_z`), `orientation`=VALUES(`orientation`);

SELECT '20261011-04_classic_areatrigger_spawns_forever_69893_70205' WHERE NOT EXISTS (SELECT 1 FROM `world_db_version` WHERE `LastUpdate`='20261011-04_classic_areatrigger_spawns_forever_69893_70205');
